<script>const cfg=<?=json_encode($config,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const token=localStorage.getItem('admin_token')||sessionStorage.getItem('admin_token')||'';const clear=()=>{try{localStorage.removeItem('admin_token');}catch(_){}try{sessionStorage.removeItem('admin_token');}catch(_){}document.cookie='admin_token=; path=/; max-age=0; SameSite=Lax';};const login=()=>location.replace(cfg.loginUrl);const esc=v=>String(v??'-').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function start(){if(!token)return login();try{const guard=await fetch(cfg.apiDashboardUrl,{headers:{Authorization:'Bearer '+token,Accept:'application/json'}});if(!guard.ok){clear();return login();}const guardData=await guard.json();const section=<?=json_encode($key)?>;if(section==='profil'){setupAdminProfile();await loadAdminProfile();return;}if(section==='fasilitas'){setupFacilities();await loadFacilities();return;}if(section==='ulasan'){setupReviews();await loadReviews();return;}if(section==='pengguna'){setupUsers();await loadUsers();return;}const res=await fetch(cfg.apiUrl,{headers:{Authorization:'Bearer '+token,Accept:'application/json'}});const json=await res.json();if(!res.ok)throw new Error(json.message||'Gagal memuat data.');const rows=Array.isArray(json.data)?json.data:(json.data?[json.data]:[]);if(section==='kategori'){const categoryPhoto=name=>{const n=String(name||'').toLocaleLowerCase('id-ID');if(n.includes('alam')||n.includes('gunung'))return '../assets/images/telaga.png?v=20261112-exact';if(n.includes('air')||n.includes('curug')||n.includes('air terjun'))return '../assets/images/kategori-air-curug.jpeg?v=20261112-exact';if(n.includes('buatan')||n.includes('kuliner'))return '../assets/images/kategori-buatan-kuliner.jpeg?v=20261112-exact';if(n.includes('sejarah')||n.includes('budaya'))return '../assets/images/kategori-sejarah-budaya.jpeg?v=20261112-exact';return '../assets/images/img.png';};document.getElementById('resourceHead').innerHTML='<tr><th>No</th><th>Foto</th><th>Kategori</th><th>Jumlah Wisata</th></tr>';document.getElementById('resourceRows').innerHTML=rows.length?rows.map((r,i)=>'<tr><td class="kategori-number" data-label="No">'+(i+1)+'</td><td class="kategori-photo" data-label="Foto"><img src="'+categoryPhoto(r.name)+'" alt="Foto '+esc(r.name)+'" loading="lazy"></td><td class="kategori-name" data-label="Kategori">'+esc(r.name)+'</td><td class="kategori-total" data-label="Jumlah wisata">'+esc(r.total_destinations??0)+'</td></tr>').join(''):'<tr><td colspan="4" class="text-center py-4">Belum ada data kategori.</td></tr>';document.getElementById('resourceMessage').textContent='Data berhasil dimuat ('+rows.length+' kategori).';}else{let cols=section==='fasilitas'?['id','name','icon_code','description']:section==='pengguna'?['id','nama','email','no_telepon']:['id_ulasan','nama_pengguna','nama_wisata','rating','komentar','tanggal_ulasan'];document.getElementById('resourceHead').innerHTML='<tr>'+cols.map(c=>'<th>'+esc(c.replaceAll('_',' '))+'</th>').join('')+'</tr>';document.getElementById('resourceRows').innerHTML=rows.length?rows.map(r=>'<tr>'+cols.map(c=>'<td>'+esc(r[c])+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+cols.length+'" class="text-center py-4">Belum ada data.</td></tr>';document.getElementById('resourceMessage').textContent='Data berhasil dimuat ('+rows.length+' data).';}}catch(e){document.getElementById('resourceMessage').textContent=e.message||'Terjadi kesalahan.';}}
const facilityModal=document.getElementById('facilityModal');
function facilityStatus(message,isError=false){const el=document.getElementById('resourceMessage');if(el){el.textContent=message;el.classList.toggle('is-error',isError);}}
function facilityShowModal(id){const el=document.getElementById(id);el.classList.add('is-open');el.setAttribute('aria-hidden','false');document.body.classList.add('facility-feedback-open');}
function facilityHideModal(id){const el=document.getElementById(id);el.classList.remove('is-open');el.setAttribute('aria-hidden','true');if(!document.querySelector('.facility-feedback-modal.is-open'))document.body.classList.remove('facility-feedback-open');}
function facilityShowResult(success,title,message,retry){const icon=document.getElementById('facilityResultIcon'),button=document.getElementById('facilityResultOk');icon.className='facility-result-icon '+(success?'is-success':'is-error');icon.innerHTML=success?'<i class="bi bi-check-lg"></i>':'<i class="bi bi-x-lg"></i>';document.getElementById('facilityResultTitle').textContent=title;document.getElementById('facilityResultText').textContent=message;button.textContent=success?'OK':'Coba Lagi';button.onclick=()=>{facilityHideModal('facilityResultModal');if(!success&&typeof retry==='function')retry();};facilityShowModal('facilityResultModal');}
async function facilityRequest(url=cfg.apiUrl,options={}){const headers={Authorization:'Bearer '+token,Accept:'application/json',...(options.headers||{})};if(options.body && !(options.body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch(url,{...options,headers});let payload={};try{payload=await response.json();}catch(_){payload={};}if(response.status===403){clear();login();throw new Error('Sesi admin berakhir. Silakan login kembali.');}if(!response.ok)throw new Error(payload.message||'Permintaan fasilitas gagal diproses.');return payload;}
function facilityModalOpen(item=null){
 const form=document.getElementById('facilityForm');
 form.reset();
 ['facilityNameError','facilityIconError','facilityFormError'].forEach(id=>document.getElementById(id).textContent='');
 document.getElementById('facilityModalTitle').textContent=item?'Edit Fasilitas':'Tambah Fasilitas';
 form.dataset.facilityId=item?String(item.id):'';
 document.getElementById('facilityName').value=item?.name||item?.tourism_name||'';
 const selected=String(item?.icon_code||'').split(/[;,|]/).map(v=>v.trim()).filter(Boolean);
 form.querySelectorAll('input[name="facility_types"]').forEach(input=>{input.checked=selected.includes(input.value);});
 if(facilityModal){facilityModal.classList.add('is-open');facilityModal.setAttribute('aria-hidden','false');document.body.classList.add('facility-modal-open');document.getElementById('facilityName').focus();}
}
function facilityModalClose(){
 if(facilityModal){
  facilityModal.classList.remove('is-open');
  facilityModal.setAttribute('aria-hidden','true');
  document.body.classList.remove('facility-modal-open');
 }
 const sug=document.getElementById('facilitySuggestions');
 if(sug){sug.innerHTML='';sug.hidden=true;}
}
let pendingFacilityDelete=null;
function setupFacilities(){
 const addBtn=document.getElementById('addFacilityButton');if(addBtn)addBtn.addEventListener('click',()=>facilityModalOpen());

 // AUTOCOMPLETE NAMA WISATA
 const wisataInput = document.getElementById('facilityName');
 const wisataSuggestions = document.getElementById('wisataSuggestions');

 let wisataTimer = null;
 let wisataRequestId = 0;

 wisataInput.addEventListener('input', function () {

     clearTimeout(wisataTimer);

     const keyword = this.value.trim();

     wisataSuggestions.innerHTML = '';
     wisataSuggestions.hidden = true;

     if (keyword.length < 2) {
         return;
     }

     wisataTimer = setTimeout(async function () {

         const requestId = ++wisataRequestId;

         try {
             const result = await facilityRequest(
                 cfg.apiWisataSearchUrl +
                 '?q=' + encodeURIComponent(keyword)
             );

             // Abaikan hasil pencarian lama
             if (requestId !== wisataRequestId) return;

             const wisataList = result.data || [];

             wisataSuggestions.innerHTML = '';

             if (!wisataList.length) {
                 const empty = document.createElement('div');
                 empty.className = 'wisata-suggestion-empty';
                 empty.textContent = 'Wisata tidak ditemukan';
                 wisataSuggestions.appendChild(empty);
             } else {

                 wisataList.forEach(function (wisata) {

                     const button = document.createElement('button');

                     button.type = 'button';
                     button.className = 'wisata-suggestion-item';
                     button.textContent = wisata.nama_wisata;

                     button.addEventListener('click', function () {

                         wisataInput.value = wisata.nama_wisata;

                         wisataSuggestions.innerHTML = '';
                         wisataSuggestions.hidden = true;

                     });

                     wisataSuggestions.appendChild(button);

                 });
             }

             wisataSuggestions.hidden = false;

         } catch (error) {

             if (requestId !== wisataRequestId) return;

             console.error('Pencarian wisata:', error);

             wisataSuggestions.innerHTML = '';

             const errorItem = document.createElement('div');
             errorItem.className = 'wisata-suggestion-empty';
             errorItem.textContent = 'Gagal mengambil saran wisata';

             wisataSuggestions.appendChild(errorItem);
             wisataSuggestions.hidden = false;
         }

     }, 300);

 });

 // Tutup saran jika klik di luar
 document.addEventListener('click', function (event) {

     if (!wisataInput.contains(event.target) &&
         !wisataSuggestions.contains(event.target)) {

         wisataSuggestions.hidden = true;
     }

 });

 if(facilityModal){facilityModal.querySelectorAll('[data-close-facility-modal]').forEach(el=>el.addEventListener('click',facilityModalClose));document.addEventListener('keydown',event=>{if(event.key==='Escape'){facilityModalClose();facilityHideModal('facilityConfirmModal');facilityHideModal('facilityResultModal');}});}
 document.querySelectorAll('[data-facility-confirm-close]').forEach(el=>el.addEventListener('click',()=>{facilityHideModal('facilityConfirmModal');pendingFacilityDelete=null;}));
 document.getElementById('facilityResultModal').querySelector('.facility-feedback-backdrop').addEventListener('click',()=>facilityHideModal('facilityResultModal'));
 const rows=document.getElementById('resourceRows');if(rows)rows.addEventListener('click',async event=>{const button=event.target.closest('[data-facility-action]');if(!button)return;const id=button.dataset.id;try{if(button.dataset.facilityAction==='edit'){const result=await facilityRequest(cfg.apiUrl+'/'+encodeURIComponent(id));facilityModalOpen(result.data||{});}else if(button.dataset.facilityAction==='delete'){const row=facilitiesCache.find(item=>String(item.id)===String(id));if(!row)return;pendingFacilityDelete={id,button};facilityShowModal('facilityConfirmModal');}}catch(error){facilityShowResult(false,'Gagal di Hapus !','Fasilitas gagal di hapus dari data detail wisata');}});
 document.getElementById('facilityConfirmDelete').addEventListener('click',async()=>{if(!pendingFacilityDelete)return;const {id,button}=pendingFacilityDelete,confirmButton=document.getElementById('facilityConfirmDelete');confirmButton.disabled=true;confirmButton.textContent='Menghapus...';try{await facilityRequest(cfg.apiUrl+'/'+encodeURIComponent(id),{method:'DELETE'});facilityHideModal('facilityConfirmModal');pendingFacilityDelete=null;await loadFacilities(false);facilityShowResult(true,'Berhasil di Hapus!','Fasilitas berhasil dihapus dari data detail wisata');}catch(error){facilityHideModal('facilityConfirmModal');facilityShowResult(false,'Gagal di Hapus !','Fasilitas gagal di hapus dari data detail wisata',()=>{if(button)button.disabled=false;facilityShowModal('facilityConfirmModal');});}finally{confirmButton.disabled=false;confirmButton.textContent='Ya, Hapus Fasilitas';}});
 const form=document.getElementById('facilityForm');if(form)form.addEventListener('submit',saveFacility);
 setupFacilityTourismAutocomplete();
}
function setupFacilityTourismAutocomplete(){
 const input=document.getElementById('facilityName');
 const box=document.getElementById('facilitySuggestions');
 if(!input||!box)return;
 let debounceTimer=null;
 let activeIndex=-1;

 function closeSuggestions(){
  box.innerHTML='';
  box.hidden=true;
  activeIndex=-1;
 }

 function selectItem(name){
  input.value=name;
  closeSuggestions();
  input.focus();
  const errorName=document.getElementById('facilityNameError');
  if(errorName)errorName.textContent='';
 }

 input.addEventListener('input',()=>{
  const val=input.value.trim();
  clearTimeout(debounceTimer);
  if(val.length<2){
   closeSuggestions();
   return;
  }
  debounceTimer=setTimeout(async()=>{
   try{
    const searchUrl=cfg.apiDestinationsSearchUrl?cfg.apiDestinationsSearchUrl+'?q='+encodeURIComponent(val):'';
    if(!searchUrl)return;
    const res=await fetch(searchUrl,{headers:{Accept:'application/json'}});
    const json=await res.json();
    const list=Array.isArray(json.data)?json.data:[];
    if(!list.length){
     box.innerHTML='<div class="facility-suggestion-empty">Tidak ada nama wisata ditemukan</div>';
     box.hidden=false;
     return;
    }
    box.innerHTML=list.slice(0,8).map((item,idx)=>{
     const name=item.name||item.nama_wisata||'';
     const cat=item.category||item.nama_kategori||'';
     const region=item.kabupaten||item.region||item.domisili||'';
     const sub=cat||region?[cat,region].filter(Boolean).join(' • '):'';
     return '<div class="facility-suggestion-item" data-index="'+idx+'" data-name="'+esc(name)+'"><div class="facility-suggestion-title">'+esc(name)+'</div>'+(sub?'<div class="facility-suggestion-sub">'+esc(sub)+'</div>':'')+'</div>';
    }).join('');
    box.hidden=false;
    activeIndex=-1;
   }catch(_){
    closeSuggestions();
   }
  },250);
 });

 box.addEventListener('click',e=>{
  const item=e.target.closest('.facility-suggestion-item');
  if(item && item.dataset.name){
   selectItem(item.dataset.name);
  }
 });

 input.addEventListener('keydown',e=>{
  if(box.hidden)return;
  const items=box.querySelectorAll('.facility-suggestion-item');
  if(!items.length)return;
  if(e.key==='ArrowDown'){
   e.preventDefault();
   activeIndex=(activeIndex+1)%items.length;
   items.forEach((el,i)=>el.classList.toggle('is-active',i===activeIndex));
   items[activeIndex]?.scrollIntoView({block:'nearest'});
  }else if(e.key==='ArrowUp'){
   e.preventDefault();
   activeIndex=(activeIndex-1+items.length)%items.length;
   items.forEach((el,i)=>el.classList.toggle('is-active',i===activeIndex));
   items[activeIndex]?.scrollIntoView({block:'nearest'});
  }else if(e.key==='Enter'){
   if(activeIndex>=0 && items[activeIndex]){
    e.preventDefault();
    selectItem(items[activeIndex].dataset.name);
   }
  }else if(e.key==='Escape'){
   closeSuggestions();
  }
 });

 document.addEventListener('click',e=>{
  if(!input.contains(e.target)&&!box.contains(e.target)){
   closeSuggestions();
  }
 });
}
function facilityIconMarkup(code){
 const map={parking:['Area Parkir',`<?=facility_svg_icon('parking')?>`],toilet:['Toilet',`<?=facility_svg_icon('toilet')?>`],wifi:['WiFi',`<?=facility_svg_icon('wifi')?>`],camera:['Spot Foto',`<?=facility_svg_icon('camera')?>`],mosque:['Mushola',`<?=facility_svg_icon('mosque')?>`]};
 const entry=map[String(code||'').trim().toLowerCase()];
 return entry?'<div class="facility-entry"><span class="facility-icon-chip">'+entry[1]+'</span><span>'+entry[0]+'</span></div>':'';
}
let facilitiesCache=[];let facilityPage=1;const facilityPageSize=5;
function renderFacilityTable(){
 const total=facilitiesCache.length,pages=Math.max(1,Math.ceil(total/facilityPageSize));facilityPage=Math.min(facilityPage,pages);
 const start=(facilityPage-1)*facilityPageSize,shown=facilitiesCache.slice(start,start+facilityPageSize);
 document.getElementById('resourceHead').innerHTML='<tr><th>No</th><th>Nama Wisata</th><th>Nama Fasilitas</th><th>Aksi</th></tr>';
 document.getElementById('resourceRows').innerHTML=shown.length?shown.map((item,index)=>{
  const name=item.name||item.facility_name||item.nama_fasilitas||'-';
  const tourism=item.tourism_name||item.nama_wisata||item.destination_name||item.wisata||name;
  const selected=String(item.icon_code||'').split(/[;,|]/).map(v=>v.trim()).filter(Boolean);
  const facilityMarkup=selected.map(facilityIconMarkup).join('')||'<span>—</span>';
  const actionMarkup='<span class="facility-entry-actions"><button type="button" class="facility-action-button is-edit" data-facility-action="edit" data-id="'+esc(item.id)+'" aria-label="Edit '+esc(name)+'"><img src="../assets/icons/action-edit.svg" alt=""></button><button type="button" class="facility-action-button is-delete" data-facility-action="delete" data-id="'+esc(item.id)+'" aria-label="Hapus '+esc(name)+'"><img src="../assets/icons/action-delete.svg" alt=""></button></span>';
  return '<tr><td data-label="No" class="facility-number">'+(start+index+1)+'</td><td data-label="Nama Wisata" class="facility-destination">'+esc(tourism)+'</td><td data-label="Nama Fasilitas" class="facility-icons-cell"><div class="facility-entries">'+facilityMarkup+'</div></td><td data-label="Aksi"><div class="facility-actions">'+actionMarkup+'</div></td></tr>';
 }).join(''):'<tr><td colspan="4" class="facility-empty">Belum ada data fasilitas. Klik Tambah Fasilitas untuk membuat data pertama.</td></tr>';
 const rangeEl=document.getElementById('facilityRange');if(rangeEl)rangeEl.textContent=total?'Menampilkan '+(start+1)+'-'+Math.min(start+facilityPageSize,total)+' dari '+total+' data fasilitas':'Menampilkan 0-0 dari 0 data fasilitas';
 const nav=document.getElementById('facilityPagination');if(nav){nav.innerHTML='';if(pages>1){const make=(label,page,disabled=false,active=false)=>{const b=document.createElement('button');b.type='button';b.className='facility-page-button'+(active?' is-active':'');b.innerHTML=label;b.disabled=disabled;b.addEventListener('click',()=>{facilityPage=page;renderFacilityTable();});nav.appendChild(b);};make('<i class="bi bi-chevron-left"></i>',Math.max(1,facilityPage-1),facilityPage===1);for(let n=1;n<=pages;n++){if(pages>5&&n>2&&n<pages-1&&Math.abs(n-facilityPage)>1){if(n===3||n===pages-2){const dots=document.createElement('span');dots.className='facility-page-dots';dots.textContent='...';nav.appendChild(dots);}continue;}make(String(n),n,false,n===facilityPage);}make('<i class="bi bi-chevron-right"></i>',Math.min(pages,facilityPage+1),facilityPage===pages);}}
}
async function loadFacilities(showLoading=true){if(showLoading)facilityStatus('Memuat data fasilitas...');try{const result=await facilityRequest();facilitiesCache=Array.isArray(result.data)?result.data:[];facilityPage=1;renderFacilityTable();facilityStatus('Data berhasil dimuat ('+facilitiesCache.length+' fasilitas).');}catch(error){facilityStatus(error.message,true);document.getElementById('resourceHead').innerHTML='';document.getElementById('resourceRows').innerHTML='<tr><td colspan="4" class="facility-empty">Data fasilitas gagal dimuat. Periksa koneksi API dan migrasi database.</td></tr>';const rangeEl=document.getElementById('facilityRange');if(rangeEl)rangeEl.textContent='';const nav=document.getElementById('facilityPagination');if(nav)nav.innerHTML='';}}
async function saveFacility(event){
 event.preventDefault();
 const form=event.currentTarget,id=form.dataset.facilityId;
 const name=document.getElementById('facilityName').value.trim();
 const selected=[...form.querySelectorAll('input[name="facility_types"]:checked')].map(input=>input.value);
 const errorName=document.getElementById('facilityNameError'),errorIcons=document.getElementById('facilityIconError'),errorBox=document.getElementById('facilityFormError');
 const saveButton=document.getElementById('saveFacilityButton');
 errorName.textContent='';errorIcons.textContent='';errorBox.textContent='';
 let valid=true;
 if(!name){errorName.textContent='Nama wisata wajib diisi.';valid=false;}
 else if(name.length>150){errorName.textContent='Nama wisata maksimal 150 karakter.';valid=false;}
 else if(facilitiesCache.some(item=>String(item.name||'').trim().toLocaleLowerCase('id-ID')===name.toLocaleLowerCase('id-ID')&&String(item.id)!==String(id||''))){errorIcons.textContent=id?'Nama fasilitas sudah ada di sistem.':'Fasilitas Duplikat.';valid=false;}
 if(!selected.length){errorIcons.textContent='Fasilitas wajib dipilih.';valid=false;}
 if(!valid)return;
 const original=saveButton.innerHTML;saveButton.disabled=true;saveButton.innerHTML='<i class="bi bi-arrow-repeat"></i> Menyimpan...';
 try{
  const result=await facilityRequest(id?cfg.apiUrl+'/'+encodeURIComponent(id):cfg.apiUrl,{method:id?'PUT':'POST',body:JSON.stringify({name,icon_code:selected.join(','),description:null})});
  facilityModalClose();
  await loadFacilities(false);
  facilityShowResult(true,id?'Perubahan Berhasil di simpan!':'Berhasil di simpan!',id?'Data fasilitas berhasil diperbarui':'Data fasilitas berhasil disimpan dan sudah ditambahkan');
 }catch(error){
  const message=error.message||'Fasilitas gagal disimpan. Silakan coba kembali.';
  facilityModalClose();facilityShowResult(false,id?'Gagal Memperbarui!':'Gagal di Simpan !',id?'Data fasilitas gagal diperbarui':'Data fasilitas gagal disimpan dan belum ditambahkan',()=>document.getElementById('facilityForm').requestSubmit());
 }finally{saveButton.disabled=false;saveButton.innerHTML=original;}
}
let reviewAll=[],reviewFiltered=[],reviewPage=1,reviewPageSize=5,reviewPendingId=null;
function reviewStatus(text,error=false){const el=document.getElementById('reviewNotice');if(el){el.textContent=text;el.classList.toggle('is-error',error);}}
async function reviewRequest(url=cfg.apiUrl,options={}){const response=await fetch(url,{...options,headers:{Authorization:'Bearer '+token,Accept:'application/json',...(options.headers||{})}});let payload={};try{payload=await response.json();}catch(_){payload={};}if(response.status===403){clear();login();throw new Error('Sesi admin berakhir. Silakan login kembali.');}if(!response.ok)throw new Error(payload.message||'Permintaan ulasan gagal diproses.');return payload;}
function reviewDate(value){if(!value)return '-';const d=new Date(String(value).replace(' ','T'));return Number.isNaN(d.getTime())?String(value):new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d);}
function reviewShowModal(id,show){const el=document.getElementById(id);el.classList.toggle('is-open',show);el.setAttribute('aria-hidden',show?'false':'true');document.body.classList.toggle('review-modal-open',document.querySelector('.review-modal.is-open')!==null);}
function reviewResult(success,message){const icon=document.getElementById('reviewResultIcon');icon.className='review-result-icon '+(success?'is-success':'is-error');icon.innerHTML=success?'<i class="bi bi-trash-fill"></i>':'<i class="bi bi-x-lg"></i>';document.getElementById('reviewResultTitle').textContent=success?'Berhasil di Hapus!':'Gagal di Hapus !';document.getElementById('reviewResultText').textContent=message;reviewShowModal('reviewResultModal',true);}
function renderReviewTable(){const tbody=document.getElementById('reviewRows'),empty=document.getElementById('reviewEmpty'),total=reviewFiltered.length,pages=Math.max(1,Math.ceil(total/reviewPageSize));reviewPage=Math.min(reviewPage,pages);const start=(reviewPage-1)*reviewPageSize,shown=reviewFiltered.slice(start,start+reviewPageSize);tbody.innerHTML=shown.map((r,i)=>'<tr><td data-label="No">'+(start+i+1)+'</td><td data-label="Nama pengguna">'+esc(r.nama_pengguna||r.nama_user||'-')+'</td><td data-label="Wisata">'+esc(r.nama_wisata||r.destination_name||'-')+'</td><td data-label="Rating"><span class="review-stars" aria-label="Rating '+Number(r.rating||0)+' dari 5">'+Array.from({length:5},(_,n)=>'<i class="bi '+(n<Math.round(Number(r.rating)||0)?'bi-star-fill':'bi-star')+'"></i>').join('')+'</span></td><td data-label="Komentar">'+esc(r.komentar||'-')+'</td><td data-label="Tanggal">'+esc(reviewDate(r.tanggal_ulasan))+'</td><td data-label="Aksi"><button type="button" class="review-delete-button" data-review-delete="'+esc(r.id_ulasan)+'" aria-label="Hapus ulasan"><i class="bi bi-trash-fill"></i></button></td></tr>').join('');
const noData=total===0;empty.hidden=!noData;tbody.closest('table').style.display='';if(noData){const hasSearch=document.getElementById('reviewSearch').value.trim()||document.getElementById('reviewRating').value;empty.innerHTML=hasSearch?'<div class="review-empty-icon is-search"><svg width="67" height="67" viewBox="0 0 67 67" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M11.1673 53.0417H19.5423V58.625C19.5423 59.63 20.0727 60.5513 20.9661 61.0537C21.3929 61.2945 21.8756 61.4187 22.3656 61.4138C22.8557 61.4089 23.3358 61.2751 23.7577 61.0258L37.0461 53.0417H55.8061C58.8769 53.0417 61.3894 50.5292 61.3894 47.4583V13.9583C61.3894 10.8875 58.8769 8.375 55.8061 8.375H11.1673C8.09648 8.375 5.58398 10.8875 5.58398 13.9583V47.4583C5.58398 50.5292 8.09648 53.0417 11.1673 53.0417ZM11.1673 13.9583H55.834V47.4583H36.2923C35.7898 47.4583 35.2873 47.5979 34.8686 47.8492L25.1257 53.6837V50.25C25.1257 48.7146 23.8694 47.4583 22.334 47.4583H11.1673V13.9583Z" fill="#166C5C"/><path d="M27.1067 41.0657L33.4997 34.6449L39.8926 41.0657L43.8567 37.1016L37.4359 30.7086L43.8567 24.3157L39.8926 20.3516L33.4997 26.7724L27.1067 20.3516L23.1426 24.3157L29.5634 30.7086L23.1426 37.1016L27.1067 41.0657Z" fill="#166C5C"/></svg></div><h2>Ulasan tidak di temukan</h2><p>Ulasan yang anda cari tidak di temukan</p>':'<div class="review-empty-icon"><svg width="67" height="67" viewBox="0 0 67 67" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M11.1673 53.0417H19.5423V58.625C19.5423 59.63 20.0727 60.5513 20.9661 61.0537C21.3929 61.2945 21.8756 61.4187 22.3656 61.4138C22.8557 61.4089 23.3358 61.2751 23.7577 61.0258L37.0461 53.0417H55.8061C58.8769 53.0417 61.3894 50.5292 61.3894 47.4583V13.9583C61.3894 10.8875 58.8769 8.375 55.8061 8.375H11.1673C8.09648 8.375 5.58398 10.8875 5.58398 13.9583V47.4583C5.58398 50.5292 8.09648 53.0417 11.1673 53.0417ZM11.1673 13.9583H55.834V47.4583H36.2923C35.7898 47.4583 35.2873 47.5979 34.8686 47.8492L25.1257 53.6837V50.25C25.1257 48.7146 23.8694 47.4583 22.334 47.4583H11.1673V13.9583Z" fill="#166C5C"/><path d="M27.1067 41.0657L33.4997 34.6449L39.8926 41.0657L43.8567 37.1016L37.4359 30.7086L43.8567 24.3157L39.8926 20.3516L33.4997 26.7724L27.1067 20.3516L23.1426 24.3157L29.5634 30.7086L23.1426 37.1016L27.1067 41.0657Z" fill="#166C5C"/></svg></div><h2>Belum ada ulasan dari pengguna</h2><p>Saat ini belum ada ulasan dari pengguna<br>di website Explore MajaKu</p>';}
document.getElementById('reviewRange').textContent=total?'Menampilkan '+(start+1)+'-'+Math.min(start+reviewPageSize,total)+' dari '+total+' data ulasan':'Menampilkan 0-0 dari 0 data ulasan';const nav=document.getElementById('reviewPagination');nav.innerHTML='';if(pages>1){const add=(label,page,disabled=false,active=false)=>{const b=document.createElement('button');b.type='button';b.className='review-page-button'+(active?' is-active':'');b.innerHTML=label;b.disabled=disabled;b.addEventListener('click',()=>{reviewPage=page;renderReviewTable();});nav.appendChild(b);};add('<i class="bi bi-chevron-left"></i>',Math.max(1,reviewPage-1),reviewPage===1);for(let n=1;n<=pages;n++){if(pages>5&&n>2&&n<pages-1&&Math.abs(n-reviewPage)>1){if(n===3||n===pages-2){const dots=document.createElement('span');dots.textContent='...';nav.appendChild(dots);}continue;}add(String(n),n,false,n===reviewPage);}add('<i class="bi bi-chevron-right"></i>',Math.min(pages,reviewPage+1),reviewPage===pages);}}
function filterReviews(){const q=document.getElementById('reviewSearch').value.trim().toLocaleLowerCase('id-ID'),rating=document.getElementById('reviewRating').value;reviewFiltered=reviewAll.filter(r=>{const hay=[r.nama_pengguna,r.nama_user,r.nama_wisata,r.komentar].join(' ').toLocaleLowerCase('id-ID');return (!q||hay.includes(q))&&(!rating||Math.round(Number(r.rating))===Number(rating));});reviewPage=1;reviewStatus(q||rating?(reviewFiltered.length?'':'Ulasan yang anda cari tidak di temukan'):'');renderReviewTable();}
async function loadReviews(){reviewStatus('');document.getElementById('reviewRows').innerHTML='<tr><td colspan="7" class="review-loading">Memuat data ulasan...</td></tr>';try{const result=await reviewRequest();reviewAll=Array.isArray(result.data)?result.data:[];filterReviews();if(reviewAll.length)reviewStatus('');}catch(error){document.getElementById('reviewRows').innerHTML='';document.querySelector('.review-table').style.display='';document.getElementById('reviewEmpty').hidden=false;document.getElementById('reviewEmpty').innerHTML='<div class="review-empty-icon is-error"><i class="bi bi-x-lg"></i></div><h2 class="is-error-text">Gagal memuat data ulasan</h2><p>Maaf, Data ulasan gagal di muat.<br>silahkan coba kembali.</p><button type="button" class="review-retry-button" id="reviewRetry">Coba lagi</button>';document.getElementById('reviewRetry').onclick=loadReviews;document.getElementById('reviewRange').textContent='';document.getElementById('reviewPagination').innerHTML='';}}
function setupReviews(){document.getElementById('reviewSearchButton').addEventListener('click',filterReviews);document.getElementById('reviewSearch').addEventListener('keydown',e=>{if(e.key==='Enter')filterReviews();});document.getElementById('reviewRating').addEventListener('change',filterReviews);document.getElementById('reviewRows').addEventListener('click',e=>{const b=e.target.closest('[data-review-delete]');if(!b)return;const row=reviewAll.find(r=>String(r.id_ulasan)===String(b.dataset.reviewDelete));if(!row)return;reviewPendingId=row.id_ulasan;document.getElementById('reviewDeleteName').textContent=row.nama_pengguna||row.nama_user||'pengguna';reviewShowModal('reviewConfirmModal',true);});document.querySelectorAll('[data-review-close]').forEach(b=>b.addEventListener('click',()=>reviewShowModal('reviewConfirmModal',false)));document.getElementById('reviewConfirmDelete').addEventListener('click',async()=>{if(!reviewPendingId)return;const button=document.getElementById('reviewConfirmDelete');button.disabled=true;button.textContent='Menghapus...';try{const result=await reviewRequest(cfg.apiUrl+'/'+encodeURIComponent(reviewPendingId),{method:'DELETE'});reviewShowModal('reviewConfirmModal',false);reviewPendingId=null;await loadReviews();reviewResult(true,result.message||'Ulasan dari pengguna tersebut telah di hapus dari data ulasan');}catch(error){reviewShowModal('reviewConfirmModal',false);reviewResult(false,'Ulasan dari pengguna tersebut gagal di hapus dari data ulasan');}finally{button.disabled=false;button.textContent='Ya, Hapus Ulasan';}});document.getElementById('reviewResultOk').addEventListener('click',()=>reviewShowModal('reviewResultModal',false));document.querySelector('[data-review-result-close]').addEventListener('click',()=>reviewShowModal('reviewResultModal',false));document.addEventListener('keydown',e=>{if(e.key==='Escape'){reviewShowModal('reviewConfirmModal',false);reviewShowModal('reviewResultModal',false);}});}

let userPage=1,userQuery='',userTotal=0,userTotalUsers=0,userTotalPages=0,userRequestSequence=0;
const userPageSize=5;
function userNotice(message='',error=false){const el=document.getElementById('userNotice');if(!el)return;el.textContent=message;el.classList.toggle('is-error',error);}
function userDate(value){if(!value)return '-';const raw=String(value).trim();const match=raw.match(/^(\d{1,2})\s+([A-Za-zÀ-ÿ]+)\s+(\d{4})$/);if(match)return match[1]+'/'+({'Jan':'01','Feb':'02','Mar':'03','Apr':'04','Mei':'05','May':'05','Jun':'06','Jul':'07','Agu':'08','Aug':'08','Sep':'09','Okt':'10','Oct':'10','Nov':'11','Des':'12','Dec':'12'}[match[2]]||match[2])+'/'+match[3];const d=new Date(raw.replace(' ','T'));return Number.isNaN(d.getTime())?raw:new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d);}
async function userRequest(page=1,search=''){const url=new URL(cfg.apiUrl,window.location.href);url.searchParams.set('page',String(page));url.searchParams.set('limit',String(userPageSize));if(search)url.searchParams.set('search',search);const response=await fetch(url.toString(),{headers:{Authorization:'Bearer '+token,Accept:'application/json'},cache:'no-store'});let payload={};try{payload=await response.json();}catch(_){payload={};}if(response.status===403){clear();login();throw new Error('Sesi admin berakhir. Silakan login kembali.');}if(!response.ok){const error=new Error(payload.message||'Gagal memuat daftar pengguna.');error.status=response.status;error.apiStatus=payload.status;throw error;}return payload;}
function userRenderPagination(){const nav=document.getElementById('userPagination');nav.innerHTML='';if(userTotalPages<=1)return;const add=(label,page,disabled=false,active=false,aria='')=>{const b=document.createElement('button');b.type='button';b.className='user-page-button'+(active?' is-active':'');b.disabled=disabled;b.innerHTML=label;b.setAttribute('aria-label',aria||('Halaman '+page));b.addEventListener('click',()=>loadUsers(page,userQuery));nav.appendChild(b);};add('<i class="bi bi-chevron-left"></i>',Math.max(1,userPage-1),userPage===1,false,'Halaman sebelumnya');let pages=[];if(userTotalPages<=5){for(let n=1;n<=userTotalPages;n++)pages.push(n);}else{pages=[1];if(userPage>3)pages.push('...');for(let n=Math.max(2,userPage-1);n<=Math.min(userTotalPages-1,userPage+1);n++)pages.push(n);if(userPage<userTotalPages-2)pages.push('...');pages.push(userTotalPages);}let last='';pages.forEach(n=>{if(n==='...'){if(last!=='...'){const dots=document.createElement('span');dots.className='user-page-dots';dots.textContent='...';nav.appendChild(dots);}last=n;return;}add(String(n),n,false,n===userPage);last=n;});add('<i class="bi bi-chevron-right"></i>',Math.min(userTotalPages,userPage+1),userPage===userTotalPages,false,'Halaman berikutnya');}
function userShowError(server=false){const table=document.querySelector('.user-table'),state=document.getElementById('userErrorState');table.style.display='none';state.hidden=false;document.getElementById('userErrorTitle').textContent=server?'Terjadi kesalahan pada server':'Gagal Memuat data pengguna';document.getElementById('userErrorText').innerHTML=server?'Maaf, server sedang bermasalah. silahkan<br>coba beberapa saat lagi.':'Maaf, Data pengguna gagal di muat.<br>silahkan coba kembali.';document.getElementById('userRange').textContent='';document.getElementById('userTotalSummary').textContent='Total pengguna: —';document.getElementById('userPagination').innerHTML='';userNotice('');}
async function loadUsers(page=1,search=userQuery){
 const requestId=++userRequestSequence;
 const table=document.querySelector('.user-table'),state=document.getElementById('userErrorState'),tbody=document.getElementById('userRows');
 state.hidden=true;table.style.display='table';tbody.innerHTML='<tr><td colspan="3" class="user-loading">Memuat data pengguna...</td></tr>';userNotice('');
 try{
  const result=await userRequest(page,search);
  if(requestId!==userRequestSequence)return;
  const data=Array.isArray(result.data)?result.data:[],pg=result.pagination||{};
  userPage=Number(pg.current_page)||page;userTotal=Number(pg.total_data??result.total_data)||0;
  userTotalUsers=Number(result.total_users??result.totalUsers??userTotal)||0;
  userTotalPages=Number(pg.total_pages??result.total_pages)||0;userQuery=search;
  tbody.innerHTML=data.length?data.map((r,i)=>'<tr><td data-label="No">'+((userPage-1)*userPageSize+i+1)+'</td><td data-label="Nama">'+esc(r.nama||'-')+'</td><td data-label="Email">'+esc(r.email||r.no_telepon||'-')+'</td></tr>').join(''):'<tr><td colspan="3" class="user-no-data">Tidak ada data pengguna.</td></tr>';
  const first=userTotal?((userPage-1)*userPageSize+1):0,last=Math.min(userPage*userPageSize,userTotal);
  document.getElementById('userRange').textContent='Menampilkan '+first+'-'+last+' dari '+userTotal+' hasil'+(search?' pencarian':'');
  document.getElementById('userTotalSummary').textContent='Total pengguna: '+userTotalUsers;
  userRenderPagination();
  if(search&&userTotal===0)userNotice('Pengguna dengan nama atau email tersebut tidak ditemukan.',true);
 }catch(error){
  if(requestId!==userRequestSequence)return;
  if(error.status>=500||error.apiStatus==='server_error')userShowError(true);else userShowError(false);
 }
}
function setupUsers(){const input=document.getElementById('userSearch'),button=document.getElementById('userSearchButton');const search=()=>{const raw=input.value.trim();if(raw.length>100){userNotice('Kata pencarian maksimal 100 karakter.',true);input.focus();return;}if(/[\u0000-\u001F\u007F]/.test(raw)){userNotice('Kata pencarian mengandung karakter yang tidak valid.',true);input.focus();return;}loadUsers(1,raw);};button.addEventListener('click',search);input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();search();}});input.addEventListener('input',()=>{if(input.value.length<=100)userNotice('');});document.getElementById('userRetryButton').addEventListener('click',()=>loadUsers(userPage,userQuery));}

async function adminProfileRequest(url,options={}){const headers={Authorization:'Bearer '+token,Accept:'application/json',...(options.headers||{})};if(options.body && !(options.body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch(url,{...options,headers,cache:'no-store'});let payload={};try{payload=await response.json();}catch(_){payload={};}if(response.status===403){clear();login();throw new Error('Sesi admin berakhir. Silakan login kembali.');}if(!response.ok){const error=new Error(payload.message||'Permintaan gagal diproses.');error.status=response.status;throw error;}return payload;}
function showProfileResult(success,title,message,buttonText='OK',onClose=null){const modal=document.getElementById('adminProfileResult');const icon=document.getElementById('adminProfileResultIcon');icon.className='admin-profile-result__icon '+(success?'is-success':'is-error');icon.innerHTML=success?'<i class="bi bi-check-lg"></i>':'<i class="bi bi-x-lg"></i>';document.getElementById('adminProfileResultTitle').textContent=title;document.getElementById('adminProfileResultText').textContent=message;const button=document.getElementById('adminProfileResultButton');button.textContent=buttonText;modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');button.onclick=()=>{modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');if(typeof onClose==='function')onClose();};}
let adminProfileData={};let selectedAdminPhoto=null;
async function loadAdminProfile(){try{const result=await adminProfileRequest(cfg.apiDashboardUrl.replace(/\/dashboard$/,'/profile'));adminProfileData=result.data||{};const name=adminProfileData.name||'Administrator MajaKu';document.getElementById('profileTopName').textContent='Admin 1';document.getElementById('profileDisplayName').textContent=name;document.getElementById('profileName').textContent=name;document.getElementById('profileUsername').textContent=adminProfileData.username||'-';document.getElementById('profileEmail').textContent=adminProfileData.email||'-';renderAdminProfilePhoto(adminProfileData.image_url||'');}catch(error){showProfileResult(false,'Gagal Memperbarui!','Informasi profil anda gagal dimuat.');document.getElementById('profileName').textContent='Gagal memuat profil';}}
