function profileModal(open){const modal=document.getElementById('adminProfileModal');modal.classList.toggle('is-open',open);modal.setAttribute('aria-hidden',String(!open));if(open){document.getElementById('editAdminName').value=adminProfileData.name||'';document.getElementById('editAdminUsername').value=adminProfileData.username||'';document.getElementById('editAdminEmail').textContent=adminProfileData.email||'-';document.getElementById('editAdminNameError').textContent='';selectedAdminPhoto=null;document.getElementById('editAdminPhoto').value='';renderAdminProfilePhoto(adminProfileData.image_url||'');document.getElementById('editAdminName').focus();}}
function setPasswordError(id,message){document.getElementById(id).textContent=message;}
function setupAdminProfile(){document.getElementById('editAdminProfile').addEventListener('click',()=>profileModal(true));document.querySelectorAll('[data-close-profile]').forEach(el=>el.addEventListener('click',()=>profileModal(false)));document.addEventListener('keydown',e=>{if(e.key==='Escape'){profileModal(false);const result=document.getElementById('adminProfileResult');result.classList.remove('is-open');result.setAttribute('aria-hidden','true');}});document.getElementById('editAdminPhoto').addEventListener('change',event=>{const file=event.target.files&&event.target.files[0];if(!file)return;if(!['image/jpeg','image/png'].includes(file.type)){showProfileResult(false,'Gagal Memperbarui!','Foto harus menggunakan format JPG atau PNG.');event.target.value='';return;}if(file.size>10*1024*1024){showProfileResult(false,'Gagal Memperbarui!','Ukuran foto maksimal 10 MB.');event.target.value='';return;}selectedAdminPhoto=file;const reader=new FileReader();reader.onload=()=>renderAdminProfilePhoto(String(reader.result));reader.readAsDataURL(file);});document.querySelectorAll('[data-toggle-password]').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.togglePassword);const visible=input.type==='password';input.type=visible?'text':'password';button.innerHTML='<i class="bi '+(visible?'bi-eye-fill':'bi-eye-slash-fill')+'"></i>';button.setAttribute('aria-label',visible?'Sembunyikan password':'Tampilkan password');}));['currentAdminPassword','newAdminPassword','confirmAdminPassword'].forEach(id=>document.getElementById(id).addEventListener('input',()=>{const map={currentAdminPassword:'currentPasswordError',newAdminPassword:'newPasswordError',confirmAdminPassword:'confirmPasswordError'};setPasswordError(map[id],'');}));document.getElementById('adminPasswordForm').addEventListener('submit',submitAdminPassword);document.getElementById('adminProfileForm').addEventListener('submit',saveAdminProfile);}
async function saveAdminProfile(event){event.preventDefault();const name=document.getElementById('editAdminName').value.trim();const username=document.getElementById('editAdminUsername').value.trim();const error=document.getElementById('editAdminNameError');error.textContent='';if(!name){error.textContent='Nama lengkap wajib diisi.';return;}if(name.length>255){error.textContent='Nama maksimal 255 karakter.';return;}if(!username){showProfileResult(false,'Gagal Memperbarui!','Username wajib diisi.');return;}if(username.length>100){showProfileResult(false,'Gagal Memperbarui!','Username maksimal 100 karakter.');return;}const button=document.getElementById('saveAdminProfile');button.disabled=true;button.innerHTML='<i class="bi bi-arrow-repeat"></i> Menyimpan...';try{let body;if(selectedAdminPhoto){body=new FormData();body.append('name',name);body.append('username',username);body.append('profile_photo',selectedAdminPhoto);}else{body=JSON.stringify({name,username});}const result=await adminProfileRequest(cfg.apiDashboardUrl.replace(/\/dashboard$/,'/profile'),{method:'PUT',body});adminProfileData={...adminProfileData,...(result.data||{}),name,username};document.getElementById('profileUsername').textContent=username;if(result.data&&result.data.image_url){adminProfileData.image_url=result.data.image_url;renderAdminProfilePhoto(result.data.image_url);}document.getElementById('profileDisplayName').textContent=name;document.getElementById('profileName').textContent=name;profileModal(false);showProfileResult(true,'Perubahan Berhasil di simpan!','Informasi profil anda berhasil diperbarui');}catch(err){profileModal(false);showProfileResult(false,'Gagal Memperbarui!','Informasi profil anda gagal diperbarui');}finally{button.disabled=false;button.innerHTML='<i class="bi bi-floppy"></i> Perbarui data';}}
async function submitAdminPassword(event){event.preventDefault();const current=document.getElementById('currentAdminPassword').value;const next=document.getElementById('newAdminPassword').value;const confirm=document.getElementById('confirmAdminPassword').value;let valid=true;setPasswordError('currentPasswordError','');setPasswordError('newPasswordError','');setPasswordError('confirmPasswordError','');if(!current){setPasswordError('currentPasswordError','Password saat ini wajib di isi');valid=false;}if(!next){setPasswordError('newPasswordError','Password baru wajib di isi');valid=false;}else if(next.length<8){setPasswordError('newPasswordError','Password minimal 8 karakter');valid=false;}else if(next.length>72){setPasswordError('newPasswordError','Password maksimal 72 byte');valid=false;}else if(!/[a-z]/.test(next)||!/[A-Z]/.test(next)||!/[0-9]/.test(next)||!/[^A-Za-z0-9]/.test(next)){setPasswordError('newPasswordError','Gunakan huruf besar, huruf kecil, angka, dan karakter khusus.');valid=false;}else if(next===current){setPasswordError('newPasswordError','Password baru tidak boleh sama dengan password sebelumnya');valid=false;}if(!confirm){setPasswordError('confirmPasswordError','Konfirmasi password baru wajib di isi');valid=false;}else if(confirm!==next){setPasswordError('confirmPasswordError','Konfirmasi password tidak sesuai dengan password baru');valid=false;}if(!valid)return;const button=document.getElementById('adminPasswordSubmit');button.disabled=true;button.innerHTML='<i class="bi bi-arrow-repeat"></i> Memproses...';try{await adminProfileRequest(cfg.apiDashboardUrl.replace(/\/dashboard$/,'/change-password'),{method:'PUT',body:JSON.stringify({current_password:current,new_password:next})});document.getElementById('adminPasswordForm').reset();showProfileResult(true,'Perubahan Berhasil di simpan!','Password anda berhasil diperbarui','OK',()=>{clear();login();});}catch(error){showProfileResult(false,'Gagal Memperbarui!','Password anda gagal diperbarui');}finally{button.disabled=false;button.innerHTML='<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M18.2504 12.0012C18.2504 11.8023 18.1714 11.6115 18.0307 11.4709C17.8901 11.3302 17.6993 11.2512 17.5004 11.2512H6.5C6.30109 11.2512 6.11032 11.3302 5.96967 11.4709C5.82902 11.6115 5.75 11.8023 5.75 12.0012V19.5012C5.75 19.9152 6.086 20.2512 6.5 20.2512H17.5004C17.9144 20.2512 18.2504 19.9152 18.2504 19.5012V12.0012ZM19.7504 19.5012C19.7504 20.7432 18.7424 21.7512 17.5004 21.7512H6.5C5.90326 21.7512 5.33097 21.5142 4.90901 21.0922C4.48705 20.6703 4.25 20.098 4.25 19.5012V12.0012C4.25 10.758 5.258 9.75122 6.5 9.75122H17.5004C18.7424 9.75122 19.7504 10.7592 19.7504 12.0012V19.5012Z" fill="white"/><path d="M15.2504 10.5013V7.50131C15.2466 6.64042 14.9029 5.81589 14.294 5.20726C13.6851 4.59863 12.8605 4.25518 11.9996 4.25171C11.1389 4.2555 10.3146 4.59908 9.70597 5.20768C9.09737 5.81628 8.75379 6.64063 8.75 7.50131V10.5013C8.75 10.7002 8.67098 10.891 8.53033 11.0316C8.38968 11.1723 8.19891 11.2513 8 11.2513C7.80109 11.2513 7.61032 11.1723 7.46967 11.0316C7.32902 10.891 7.25 10.7002 7.25 10.5013V7.50131C7.2538 6.2428 7.75542 5.03693 8.64532 4.14703C9.53522 3.25713 10.7411 2.75551 11.9996 2.75171C13.2583 2.75519 14.4645 3.25667 15.3547 4.14661C16.2448 5.03654 16.7466 6.2426 16.7504 7.50131V10.5013C16.7504 10.7002 16.6714 10.891 16.5307 11.0316C16.3901 11.1723 16.1993 11.2513 16.0004 11.2513C15.8015 11.2513 15.6107 11.1723 15.4701 11.0316C15.3294 10.891 15.2504 10.7002 15.2504 10.5013ZM11.2496 17.0005V14.5009C11.2496 14.4024 11.269 14.3049 11.3067 14.2139C11.3444 14.1229 11.3996 14.0402 11.4693 13.9706C11.5389 13.9009 11.6216 13.8457 11.7126 13.808C11.8036 13.7703 11.9011 13.7509 11.9996 13.7509C12.0981 13.7509 12.1956 13.7703 12.2866 13.808C12.3776 13.8457 12.4603 13.9009 12.5299 13.9706C12.5996 14.0402 12.6548 14.1229 12.6925 14.2139C12.7302 14.3049 12.7496 14.4024 12.7496 14.5009V17.0005C12.7496 17.099 12.7302 17.1965 12.6925 17.2875C12.6548 17.3785 12.5996 17.4612 12.5299 17.5308C12.4603 17.6005 12.3776 17.6557 12.2866 17.6934C12.1956 17.7311 12.0981 17.7505 11.9996 17.7505C11.9011 17.7505 11.8036 17.7311 11.7126 17.6934C11.6216 17.6557 11.5389 17.6005 11.4693 17.5308C11.3996 17.4612 11.3444 17.3785 11.3067 17.2875C11.269 17.1965 11.2496 17.099 11.2496 17.0005Z" fill="white"/></svg> Perbarui password';}}

const logoutModal = document.getElementById('logoutModal');
const logoutConfirmButton = document.getElementById('logoutConfirmButton');
const logoutCancelButton = document.getElementById('logoutCancelButton');

function openLogoutModal() {
    document.body.classList.remove('mobile-sidebar-open');
    logoutModal.hidden = false;
    document.body.classList.add('logout-modal-open');
    setTimeout(function () {
        logoutModal.classList.add('is-visible');
        logoutCancelButton.focus();
    }, 10);
}

function closeLogoutModal() {
    logoutModal.classList.remove('is-visible');
    document.body.classList.remove('logout-modal-open');
    setTimeout(function () { logoutModal.hidden = true; }, 220);
}

async function logout() {
    try {
        if (token) {
            await fetch(cfg.apiLogoutUrl, {
                method: 'POST',
                credentials: 'same-origin',
                headers: { 'Authorization': 'Bearer ' + token, 'Accept': 'application/json' }
            });
        }
    } catch (e) {
    } finally {
        clear();
        login();
    }
}


document.getElementById('logoutButton').addEventListener('click', openLogoutModal);
document.getElementById('mobileLogoutButton').addEventListener('click', openLogoutModal);
logoutCancelButton.addEventListener('click', closeLogoutModal);
document.getElementById('logoutModalBackdrop').addEventListener('click', closeLogoutModal);
logoutConfirmButton.addEventListener('click', function () {
    logoutConfirmButton.disabled = true;
    logoutCancelButton.disabled = true;
    logoutConfirmButton.textContent = 'Memproses...';
    logout();
});

document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && !logoutModal.hidden && !logoutConfirmButton.disabled) {
        closeLogoutModal();
    }
});

document.getElementById('sidebarCollapse').onclick=()=>document.body.classList.toggle('sidebar-collapsed');
document.getElementById('mobileMenuButton').onclick=()=>document.body.classList.toggle('mobile-sidebar-open');
document.getElementById('sidebarBackdrop').onclick=()=>document.body.classList.remove('mobile-sidebar-open');
start();</script>
